# Let's be more precise. For each function declared in internal/, let's:
# 1. Get the package name from the file path
# 2. Search for package.FuncName patterns or method calls .FuncName(
# This is more accurate for fan-in analysis

# First, let's build a mapping of function -> package
grep -rn '^func ' /bench/home/work/internal/ --include='*.go' | \
  perl -ne '
    if (/^([^:]+):(\d+):func\s+\(.*?\)\s+([A-Za-z_]\w*)\s*\(/) {
      print "$1:$2:$3\n";
    } elsif (/^([^:]+):(\d+):func\s+([A-Za-z_]\w*)\s*\(/) {
      print "$1:$2:$3\n";
    }
  ' | while IFS=: read -r filepath lineno funcname; do
    # Get the Go package name from the file
    pkgname=$(grep -m1 '^package ' "$filepath" | awk '{print $2}')
    echo "$filepath:$lineno:$funcname:$pkgname"
done > /tmp/funcs_with_pkg.txt

head -20 /tmp/funcs_with_pkg.txt
echo "---"
wc -l /tmp/funcs_with_pkg.txt

